; ClosedLoopMain ($14160)
; Called from: EquipmentInit
;---------------------------------------------------------------------------------------------------
ClosedLoopMain:
        BRCLR   >Options032C,#$80,L14218                 ; bit 7: closed loop off: ClosedLoopMain clears the O2 state and the short-term trim
        BCLR    >O2ActiveFlags,Z,#$F0                    ; bit 7: upstream O2 sensor 1 active: output passed O2ActiveLow (latched, cleared when closed loop restarts); bit 6: upstream O2 sensor 2 active (as bit 7); bit 5: downstream O2 sensor 1 active: output passed O2DownActiveLow; bit 4: downstream O2 sensor 2 active (as bit 5)
        CLR     >ShortTermTrim1,Z
        CLR     >O2DelayWork1,Z
        CLR     >ClosedLoop725,Z
        CLR     >ClosedLoop724,Z
        CLR     >ClosedLoop726,Z
        CLR     >ClosedLoop702,Z
        CLR     >ClosedLoop703,Z
        CLRW    >ClosedLoop704,Z
        CLR     >ClosedLoop706,Z
        CLR     >ClosedLoop707,Z
        CLRW    >ClosedLoop70C,Z
        CLR     >ClosedLoop70E,Z
        CLR     >ClosedLoop711,Z
        CLR     >ShortTermTrim2,Z
        CLR     >O2DelayWork2,Z
        CLR     >ClosedLoop74D,Z
        CLR     >ClosedLoop74C,Z
        CLR     >ClosedLoop74E,Z
        CLR     >ClosedLoop72A,Z
        CLR     >ClosedLoop72B,Z
        CLRW    >ClosedLoop72C,Z
        CLR     >ClosedLoop72E,Z
        CLR     >ClosedLoop72F,Z
        CLRW    >ClosedLoop734,Z
        CLR     >ClosedLoop736,Z
        CLR     >ClosedLoop739,Z
        BSET    >O2ResetFlags,Z,#$03                     ; bit 1: restart closed-loop learning, bank 1 (O2LearnEnable); bit 0: restart closed-loop learning, bank 2 (O2LearnEnable)
        BSET    <PurgeCellRichFlags,Z,#$40               ; bit 6: closed-loop learning restarted: purge cells to be relearnt (ClosedLoopMain, ClosedLoopManager, PurgeReset)
        CLR     >O2CellWork,Z
        CLR     >O2AdaptValue1,Z
        CLR     <PurgeCellTrim1,Z
        CLR     <PurgeCellTrim2,Z
        CLR     <PurgeCellTrim3,Z
        TZX
        LDX     #$805A
L141EE:
        CLR     $00,X
        AIX     #$01
        CPX     #$806A
        BNE     L141EE
        CLR     >O2LearnTimer2,Z
        CLR     >O2AdaptValue2,Z
        CLR     <PurgeCellTrim1B2,Z
        CLR     <PurgeCellTrim2B2,Z
        CLR     <PurgeCellTrim3B2,Z
        TZX
        LDX     #$806D
L1420C:
        CLR     $00,X
        AIX     #$01
        CPX     #$807D
        BNE     L1420C
        BRA     L1424A
L14218:
        BRCLR   >EngineStateFlags,Z,#$80,L14246          ; bit 7: engine turning: set at the first reference pulse, cleared when the engine stalls (CalcEngineRpm)
        JSR     O2CellSelect3x3
        JSR     ClosedLoopTiming
        BRCLR   >MainLoopPhaseMask,Z,#$10,L14238         ; bit 4: one pass in 32 (about 383 ms)
        CLRA
        JSR     O2CrossCheck
        LDAA    #$FF
        JSR     O2CrossCheck
L14238:
        JSR     ClosedLoopManager
        JSR     O2PostFuelCheck
        JSR     O2CellSelect
        BRA     L1424A
L14246:
        JSR     O2StartDelays
L1424A:
        RTS

